import{_ as a,a as s,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第二册：实践与进步 · 单元 2 复习与自测 · 第43–48课","description":"L25–L48 原创练习和答案解析。","frontmatter":{"title":"第二册：实践与进步 · 单元 2 复习与自测 · 第43–48课","description":"L25–L48 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-2/unit-02/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 2 复习与自测","summary":"L25–L48 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 2 复习与自测 · 第34–42课","link":"/life/english/new-concept/book-2/unit-02/review-part-02"},"next":{"text":"第二册：实践与进步 · 单元 3：从过程记录到有依据的判断","link":"/life/english/new-concept/book-2/unit-03/overview"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 2 复习与自测 · 第34–42课","link":"/life/english/new-concept/book-2/unit-02/review-part-02"},"next":{"text":"第二册：实践与进步 · 单元 3：从过程记录到有依据的判断","link":"/life/english/new-concept/book-2/unit-03/overview"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/review-part-03.md","filePath":"life/english/new-concept/book-2/unit-02/review-part-03.md"}'),n={name:"life/english/new-concept/book-2/unit-02/review-part-03.md"};function r(i,e,l,p,h,c){return s(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第二册-实践与进步-·-单元-2-复习与自测-·-第43–48课" tabindex="-1">第二册：实践与进步 · 单元 2 复习与自测 · 第43–48课 <a class="header-anchor" href="#第二册-实践与进步-·-单元-2-复习与自测-·-第43–48课" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 2 复习与自测 · 第43–48课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-02/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-43-·-情态动词的意义与形式" tabindex="-1">Lesson 43 · 情态动词的意义与形式 <a class="header-anchor" href="#lesson-43-·-情态动词的意义与形式" aria-label="Permalink to &quot;Lesson 43 · 情态动词的意义与形式 {#lesson-43-·-情态动词的意义与形式}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The pilot was able to land before the storm arrived.</p><h3 id="练习-1-18" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-18" aria-label="Permalink to &quot;练习 1 {#练习-1-18}&quot;">​</a></h3><p>填 to/for：The pilot managed ___ land safely.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> manage 后用 to 不定式表示成功完成。</p></details><p><strong>表达迁移：</strong> 写三句艰难行程，包含限制、成功行动与后续支援。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The pilot was able to land before the storm arrived. There was little fuel left. A support team brought supplies the next morning.</p><p>第一句的组织方式：was able to land 描述这次成功结果，before 从句限定时间，storm arrived 是之后的事件。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：managed landing 不符合常用搭配；用 managed to land。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-043">回看本课</a></p><h2 id="lesson-44-·-真实条件句" tabindex="-1">Lesson 44 · 真实条件句 <a class="header-anchor" href="#lesson-44-·-真实条件句" aria-label="Permalink to &quot;Lesson 44 · 真实条件句 {#lesson-44-·-真实条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If we keep to the path, we can reach the village before dark.</p><h3 id="练习-1-19" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-19" aria-label="Permalink to &quot;练习 1 {#练习-1-19}&quot;">​</a></h3><p>填 keep：If we ___ to the path, we can reach the village.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> keep</p><p><strong>解析：</strong> 真实未来条件从句通常用现在时。</p></details><p><strong>表达迁移：</strong> 规划一次徒步，写两条条件与对应行动，避免把可能当成保证。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>If we keep to the path, we can reach the village before dark. The map shows a stream halfway along the route. We will rest there if everyone agrees.</p><p>第一句的组织方式：if 从句用一般现在时 keep，主句 can reach 表条件下的能力或可能，before dark 为时间界限。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：If we will keep ... 在普通真实条件句中多余；用 If we keep。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-044">回看本课</a></p><h2 id="lesson-45-·-被动语态与信息重点" tabindex="-1">Lesson 45 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-45-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 45 · 被动语态与信息重点 {#lesson-45-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The missing money has been returned in a plain envelope.</p><h3 id="练习-1-20" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-20" aria-label="Permalink to &quot;练习 1 {#练习-1-20}&quot;">​</a></h3><p>填 has/have：The money ___ been returned.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> has</p><p><strong>解析：</strong> money 是不可数名词。</p></details><p><strong>表达迁移：</strong> 写一个匿名归还物品的简报，区分已知事实和未知身份。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The missing money has been returned in a plain envelope. No name was written on it. The owner thanked whoever had sent it.</p><p>第一句的组织方式：money 不可数，助动词用 has；has been returned 是完成时被动，in 表容器。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：money have been 应为 money has been；不可数名词按单数处理。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-045">回看本课</a></p><h2 id="lesson-46-·-数量表达与范围" tabindex="-1">Lesson 46 · 数量表达与范围 <a class="header-anchor" href="#lesson-46-·-数量表达与范围" aria-label="Permalink to &quot;Lesson 46 · 数量表达与范围 {#lesson-46-·-数量表达与范围}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The overnight train cost more but offered fewer comfortable seats.</p><h3 id="练习-1-21" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-21" aria-label="Permalink to &quot;练习 1 {#练习-1-21}&quot;">​</a></h3><p>选 less/fewer：The carriage had ___ seats.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> fewer</p><p><strong>解析：</strong> seats 是可数复数名词。</p></details><p><strong>表达迁移：</strong> 比较两种交通选择，写费用、座位和最终决定。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The overnight train cost more but offered fewer comfortable seats. We changed to a daytime service on the return trip. It was cheaper and gave us a better view.</p><p>第一句的组织方式：cost 是过去式，与原形同形；more 省略比较中的 money，fewer 修饰可数复数 seats。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：fewer comfort 不对，comfort 通常不可数；可说 less comfort 或 fewer comfortable seats。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-046">回看本课</a></p><h2 id="lesson-47-·-间接引语与视角转换" tabindex="-1">Lesson 47 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-47-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 47 · 间接引语与视角转换 {#lesson-47-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The cellar was said to be haunted, but no one had evidence.</p><h3 id="练习-1-22" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-22" aria-label="Permalink to &quot;练习 1 {#练习-1-22}&quot;">​</a></h3><p>补全：The house was said ___ be empty.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> to</p><p><strong>解析：</strong> be said to do 是报道被动结构。</p></details><p><strong>表达迁移：</strong> 写一段传闻调查，先标明说法，再写观察结果与处理行动。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The cellar was said to be haunted, but no one had evidence. A camera later recorded a loose window opening in the wind. The owner repaired its latch.</p><p>第一句的组织方式：was said to be 是被动报道结构；but no one had evidence 限定传闻可信度，不确认鬼魂存在。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：evidence 通常不可数，不写 an evidence；可说 a piece of evidence。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-047">回看本课</a></p><h2 id="lesson-48-·-时间、原因与让步从句" tabindex="-1">Lesson 48 · 时间、原因与让步从句 <a class="header-anchor" href="#lesson-48-·-时间、原因与让步从句" aria-label="Permalink to &quot;Lesson 48 · 时间、原因与让步从句 {#lesson-48-·-时间、原因与让步从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> As soon as the dentist removed the mirror, I asked a question.</p><h3 id="练习-1-23" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-23" aria-label="Permalink to &quot;练习 1 {#练习-1-23}&quot;">​</a></h3><p>选连接词：___ she finished speaking, I replied.（一……就……）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> As soon as</p><p><strong>解析：</strong> 该连接词准确表达紧接发生。</p></details><p><strong>表达迁移：</strong> 写一次不方便说话时的交流，说明非语言回应和随后提出的问题。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>As soon as the dentist removed the mirror, I asked a question. I wanted to know when I could eat. She gave me clear instructions before I left.</p><p>第一句的组织方式：As soon as 从句给出先发生的动作，主句 asked 紧接其后；两者都是具体过去事件。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：while he removed the mirror 不一定等于拿开之后；表达紧接应使用 as soon as。</p></details><p><a href="/life/english/new-concept/book-2/unit-02/lesson-048">回看本课</a></p>',52)])])}const u=a(n,[["render",r]]);export{m as __pageData,u as default};
